{
  "authorization_enabled": true,
  "predefined_policy": "rbac.v1",
  "custom_policy": "package artifacthub.authz

# By default, deny requests
default allow = false

# Allow the action if the user is allowed to perform it
allow {
  # If user's role is owner
  data.roles.owner.users[_] == input.user
}
allow {
  # If user's role is allowed to perform this action
  allowed_actions[_] == input.action
}

# Get user allowed actions
allowed_actions[action] {
  user_roles[_] == "owner"
  action := "all"
}
allowed_actions[action] {
  action := data.roles[role].allowed_actions[_]
  user_roles[_] == role
}

# Get user roles
user_roles[role] {
  data.roles[role].users[_] == input.user
}
",
  "policy_data": "{
  "roles": {
    "owner": {
      "users": ["user1"]
    },
    "customRole1": {
      "users": ["member1", "member2"],
      "allowed_actions": ["addOrganizationMember", "addOrganizationRepository"]
    }
  }
}
"
}

